from collections import deque

MOD = 1_000_000_007


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    if n == 0:
        return 1

    idx = {ch: i for i, ch in enumerate(alphabet)}
    k = len(alphabet)

    # Build the Aho-Corasick trie of banned strings.
    goto = [[-1] * k]
    bad = [False]
    for word in banned:
        node = 0
        for ch in word:
            c = idx[ch]
            if goto[node][c] == -1:
                goto[node][c] = len(goto)
                goto.append([-1] * k)
                bad.append(False)
            node = goto[node][c]
        bad[node] = True

    # Compute failure links and the full transition function (BFS order).
    fail = [0] * len(goto)
    queue = deque()
    for c in range(k):
        child = goto[0][c]
        if child == -1:
            goto[0][c] = 0
        else:
            fail[child] = 0
            queue.append(child)

    while queue:
        u = queue.popleft()
        # A state is forbidden if any suffix of it is a banned string.
        bad[u] = bad[u] or bad[fail[u]]
        for c in range(k):
            v = goto[u][c]
            if v == -1:
                goto[u][c] = goto[fail[u]][c]
            else:
                fail[v] = goto[fail[u]][c]
                queue.append(v)

    # Transition matrix over automaton states, excluding forbidden states.
    S = len(goto)
    M = [[0] * S for _ in range(S)]
    for u in range(S):
        if bad[u]:
            continue
        for c in range(k):
            v = goto[u][c]
            if not bad[v]:
                M[u][v] += 1

    def mat_mul(A, B):
        size = len(A)
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            Ai = A[i]
            Ci = C[i]
            for t in range(size):
                a = Ai[t]
                if a:
                    Bt = B[t]
                    for j in range(size):
                        Ci[j] += a * Bt[j]
            for j in range(size):
                Ci[j] %= MOD
        return C

    # Compute (e_root * M^n) by binary exponentiation, applying to a vector.
    vec = [0] * S
    vec[0] = 1
    P = M
    e = n
    while e:
        if e & 1:
            vec = [sum(vec[u] * P[u][v] for u in range(S)) % MOD for v in range(S)]
        e >>= 1
        if e:
            P = mat_mul(P, P)

    return sum(vec) % MOD
